function bindPurchaseReturn(){const f=document.getElementById('aw-preturn');if(!f)return;f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(!d.date||!awDateAllowed(d.date)||!d.supplier.trim()||!d.item.trim()||!d.reference.trim()||!Number.isFinite(Number(d.qty))||Number(d.qty)<=0||!Number.isFinite(Number(d.amount))||Number(d.amount)<0){alert('Complete supplier, reference, item, quantity and amount.');return;}purchaseReturns.push({id:uid('PR'),noteNo:awNextNo('PR',d.date),...d,qty:Number(d.qty),amount:Number(d.amount),status:'recorded'});persist();render();};}
