function bindCutting(){const f=document.getElementById('aw-cut');if(!f)return;f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),o=typeof mfg!=='undefined'&&mfg.orders.find(x=>x.id===d.moId),pieces=Number(d.pieces),issued=Number(d.issued),used=Number(d.used),wastage=Number(d.wastage),returned=Number(d.returned);if(!o||!d.date||d.date>today()||!awDateAllowed(d.date)||!d.fabric.trim()||!Number.isInteger(pieces)||pieces<1||![issued,used,wastage,returned].every(Number.isFinite)||[issued,used,wastage,returned].some(x=>x<0)||Math.abs(issued-used-wastage-returned)>.001){alert('Cutting quantities must be valid and issued metres must equal used + wastage + returned.');return;}cuttingBatches.push({id:uid('CUT'),batchNo:awNextNo('CUT',d.date),moId:o.id,style:o.style,date:d.date,fabric:d.fabric,lot:d.lot,pieces,issued,used,wastage,returned,createdAt:new Date().toISOString()});persist();render();}}


function allLocalSearchRecords(){
 const readKey=(k,d=[])=>read(k,d),out=[];
 const add=(key,type,label,items,make)=>{(items||[]).forEach(x=>out.push({type,label:make?make(x):String(x.id||x.number||x.name||''),id:x.id||x.number||'',text:JSON.stringify(x)}));};
 add('pa_customer_master_v1','Customer','Customer',readKey('pa_customer_master_v1'),x=>x.name||x.id);
 add('pa_suppliers_v1','Supplier','Supplier',readKey('pa_suppliers_v1'),x=>x.name||x.legalName||x.id);
 add('pa_orders','Sales order','Sales order',readKey('pa_orders'),x=>(x.id||'')+' · '+(x.party||''));
 add('pa_customer_purchase_orders_v1','Customer PO','Customer PO',readKey('pa_customer_purchase_orders_v1'),x=>(x.poNumber||x.number||x.id||'')+' · '+(x.customer||''));
 add('pa_tax_invoices','Tax invoice','Tax invoice',readKey('pa_tax_invoices'),x=>(x.invoice_no||x.id||'')+' · '+(x.buyer_name||''));
 add('pa_manufacturing_v1','Manufacturing order','Manufacturing order',readKey('pa_manufacturing_v1',{orders:[]}).orders||[],x=>(x.id||'')+' · '+(x.style||''));
 add('pa_dispatches_v1','Dispatch','Dispatch',readKey('pa_dispatches_v1'),x=>(x.lr||x.id||'')+' · '+(x.transporter||''));
 add('pa_purchase_orders_v1','Supplier PO','Supplier PO',readKey('pa_purchase_orders_v1'),x=>(x.number||x.id||'')+' · '+(x.supplierName||''));
 add('pa_purchase_bills_v1','Purchase bill','Purchase bill',readKey('pa_purchase_bills_v1'),x=>(x.invoiceNo||x.billNo||x.id||'')+' · '+(x.supplier||''));
 add(KEY.job,'Job-work challan','Job-work challan',jobs,x=>(x.challanNo||x.id)+' · '+x.contractor);
 add(KEY.returns,'Customer return','Customer return',returns,x=>(x.returnNo||x.id)+' · '+x.customer);
 return out;
}
function searchPage(){return card('Global search','Search local customer, supplier, PO, order, invoice, manufacturing, dispatch, purchase and job-work records.','<form id="aw-search"><label>Search all saved records<input name="q" required placeholder="Customer, GSTIN, style, PO, invoice, LR, AWB, contractor..."></label><button class="primary">Search</button></form><div id="aw-search-results"><p class="hint">Search runs only against records saved on this device.</p></div>')+card('Duplicate checks','Scan common local identifiers for possible duplicates. Review before correcting; this does not silently merge records.','<button type="button" class="primary" id="aw-duplicates">Run duplicate scan</button><div id="aw-duplicate-results"></div>')+card('CSV exports','Download readable CSV copies of selected local registers. Sensitive exports remain on this device; protect the files.','<div class="invoice-actions"><button class="secondary" data-aw-export="customers">Customers</button><button class="secondary" data-aw-export="suppliers">Suppliers</button><button class="secondary" data-aw-export="orders">Sales orders</button><button class="secondary" data-aw-export="invoices">Tax invoices</button><button class="secondary" data-aw-export="stock">Garment stock</button><button class="secondary" data-aw-export="jobwork">Job-work challans</button></div>')}
function csvSafe(v){let s=String(v??'');if(/^[\t\r ]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function downloadCSV(name,rows){const csv='\uFEFF'+rows.map(r=>r.map(csvSafe).join(',')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'-'+today()+'.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function duplicateScan(){
 const issues=[],groups=(items,key,label)=>{const map=new Map();items.forEach(x=>{const k=String(key(x)||'').trim().toLowerCase();if(!k)return;if(!map.has(k))map.set(k,[]);map.get(k).push(x)});map.forEach((xs,k)=>{if(xs.length>1)issues.push(label+': '+xs.map(x=>x.name||x.poNumber||x.invoice_no||x.id||k).join(' / '))})};
 const customers=read('pa_customer_master_v1'),suppliers=read('pa_suppliers_v1'),pos=read('pa_customer_purchase_orders_v1'),invoices=read('pa_tax_invoices'),dispatches=read('pa_dispatches_v1'),receipts=read('pa_customer_receipts_v1');
 groups(customers,x=>x.mobile,'Duplicate customer mobile');groups(customers,x=>x.gstin,'Duplicate customer GSTIN');groups(suppliers,x=>x.gstin||x.GSTIN,'Duplicate supplier GSTIN');groups(pos,x=>(x.customer||'')+'|'+(x.poNumber||x.number),'Duplicate customer PO');groups(invoices,x=>x.invoice_no,'Duplicate invoice number');groups(dispatches,x=>x.lr,'Duplicate LR number');groups(dispatches,x=>x.awb,'Duplicate AWB');groups(receipts,x=>x.reference,'Duplicate receipt reference');
 const el=document.getElementById('aw-duplicate-results');if(el)el.innerHTML=issues.length?'<div class="featurelist">'+issues.map(x=>'<div><b>Possible duplicate</b><small>'+esc(x)+'</small></div>').join('')+'</div>':'<p class="hint">No duplicate values found in the checked local registers.</p>';
}
function bindSearch(){
 const f=document.getElementById('aw-search');if(f)f.onsubmit=e=>{e.preventDefault();const q=String(new FormData(f).get('q')||'').trim().toLowerCase(),hits=allLocalSearchRecords().filter(x=>(x.type+' '+x.label+' '+x.text).toLowerCase().includes(q)).slice(0,60),el=document.getElementById('aw-search-results');el.innerHTML=hits.length?'<div class="featurelist">'+hits.map(x=>'<div><b>'+esc(x.type)+' · '+esc(x.label)+'</b><small>'+esc(x.text.slice(0,260))+'</small></div>').join('')+'</div>':'<p class="hint">No matching local records found.</p>';};
 const du=document.getElementById('aw-duplicates');if(du)du.onclick=duplicateScan;
 document.querySelectorAll('[data-aw-export]').forEach(b=>b.onclick=()=>{const k=b.dataset.awExport;let rows=[];if(k==='customers'){rows=[['Name','Mobile','GSTIN','City','State','PIN','Credit days','Credit limit','Address'],...read('pa_customer_master_v1').map(x=>[x.name,x.mobile,x.gstin,x.city,x.state,x.pincode,x.creditDays,x.creditLimit,x.address])] }else if(k==='suppliers'){rows=[['Name','Mobile','GSTIN','PAN','Constitution'],...read('pa_suppliers_v1').map(x=>[x.name||x.legalName,x.mobile,x.gstin||x.GSTIN,x.pan,x.constitution])] }else if(k==='orders'){rows=[['Order ID','Customer','Date','Status','Style/Item summary','Pieces'],...read('pa_orders').map(x=>[x.id,x.party,x.date,x.status,(x.items||[]).map(i=>i.name+' / '+(i.itemNumber||'')+' / '+(i.colour||'')+' / '+(i.size||'')).join(' | '),(x.items||[]).reduce((n,i)=>n+Number(i.qty||0),0)])] }else if(k==='invoices'){rows=[['Invoice','Customer','Date','Due date','Taxable','Tax','Total','Status'],...read('pa_tax_invoices').map(x=>[x.invoice_no,x.buyer_name,x.invoice_date,x.due_date,x.taxable,x.tax,x.grand_total,x.status])] }else if(k==='stock'){rows=[['Date','Type','Style','Colour','Size','Qty','Reference','Reason'],...read('pa_garment_stock_ledger_v1').map(x=>[x.date,x.type,x.style,x.colour,x.size,x.qty,x.reference,x.reason])] }else if(k==='jobwork'){rows=[['Challan','Contractor','Date','MO','Operation','Style','Colour','Size','Sent','Accepted','Rejected','Rework','Rate','Advance','Extras','Deductions','Paid','Payable','Status'],...jobs.map(x=>[x.challanNo,x.contractor,x.date,x.mo,x.operation,x.style,x.colour,x.size,x.sent,x.accepted,x.rejected,x.rework,x.rate,x.advance,x.extras,x.deductions,x.paid,jobPayable(x),x.status])] }downloadCSV('Prasad-'+k,rows);});
}


function financialPage(){
 const rows=financialYears.slice().sort((a,b)=>a.start.localeCompare(b.start)).map(y=>'<div class="line"><div><b>'+esc(y.name)+' · '+esc(y.start)+' to '+esc(y.end)+'</b><small>'+esc(y.status)+' · '+(y.lockedAt?'Locked '+esc(y.lockedAt.slice(0,10)):'Open')+'</small></div>'+(y.status==='Locked'?'<button class="secondary" data-aw-fy-unlock="'+esc(y.id)+'">Unlock with reason</button>':'<button class="secondary" data-aw-fy-lock="'+esc(y.id)+'">Lock year</button>')+'</div>').join('');
 const seq=Object.entries(docSequences).sort().map(([k,v])=>'<div class="line"><b>'+esc(k)+'</b><strong>'+v+'</strong></div>').join('');
 return card('Financial year setup','Create non-overlapping financial years and lock a closed year for the advanced local workflows. Existing sales, purchase, dispatch and GST forms are not yet universally period-lock aware.','<form id="aw-fy"><div class="two">'+input('start','Start date','date','required')+input('end','End date','date','required')+'</div><button class="primary">Add financial year</button></form>')+card('Financial year register','Locking blocks new entries only in the new Business Control Centre workflows; it is not a complete company-wide period lock.',rows||'<div class="empty">No financial year records. Default document numbering uses April–March.</div>')+card('Local document series','Sequence values are saved per document type and financial year for new local registers.',seq||'<div class="empty">No new documents numbered yet.</div>')+'<p class="hint">Invoice numbering remains in its existing local series. Gap-free, multi-user numbering and year-end opening-balance carry-forward require the final secure shared database and accounting phase.</p>';
}
function bindFinancial(){
 const f=document.getElementById('aw-fy');if(f)f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(!d.start||!d.end||d.end<d.start){alert('Enter a valid start and end date.');return;}if(financialYears.some(y=>d.start<=y.end&&d.end>=y.start)){alert('Financial years cannot overlap.');return;}financialYears.push({id:uid('FY'),name:fyFor(d.start),start:d.start,end:d.end,status:'Open',createdAt:new Date().toISOString()});persist();render();};
 document.querySelectorAll('[data-aw-fy-lock]').forEach(b=>b.onclick=()=>{const y=financialYears.find(x=>x.id===b.dataset.awFyLock);if(!y||y.status==='Locked')return;if(!confirm('Lock '+y.name+' for new Business Control Centre entries?'))return;y.status='Locked';y.lockedAt=new Date().toISOString();persist();render();});
 document.querySelectorAll('[data-aw-fy-unlock]').forEach(b=>b.onclick=()=>{const y=financialYears.find(x=>x.id===b.dataset.awFyUnlock);if(!y||y.status!=='Locked')return;const reason=prompt('Reason to unlock '+y.name+':');if(!reason||!reason.trim())return;y.status='Open';y.unlockedAt=new Date().toISOString();y.unlockReason=reason.trim();persist();render();});
}
function chequePage(){
 const rows=cheques.slice().reverse().map(x=>'<div class="line"><div><b>'+esc(x.number)+' · '+esc(x.party)+'</b><small>'+esc(x.kind)+' · '+money(x.amount)+' · '+esc(x.date)+' · '+esc(x.status)+'</small><small>'+esc(x.bank||'')+' · '+esc(x.reference||'')+'</small></div><button class="secondary" data-aw-cheque="'+esc(x.id)+'">Update status</button></div>').join('');
 return card('Cheque register','Track post-dated, issued, received, deposited, cleared, bounced and cancelled cheques. No bank feed or automatic accounting reversal is connected.','<form id="aw-cheque"><div class="two">'+input('number','Cheque number')+input('party','Party / payee')+'</div><div class="two"><label>Type<select name="kind"><option>Received</option><option>Issued</option></select></label><label>Cheque date<input name="date" type="date" required></label></div><div class="two">'+input('amount','Amount ₹','number','min=".01" step=".01" required')+input('bank','Bank name')+'</div>'+input('reference','Linked invoice / bill / UTR')+'<button class="primary">Save cheque</button></form>')+card('Cheque register history','Status changes are stored locally.',rows||'<div class="empty">No cheque records.</div>');
}
function bindCheque(){const f=document.getElementById('aw-cheque');if(f)f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(!d.number.trim()||!d.party.trim()||!Number.isFinite(Number(d.amount))||Number(d.amount)<=0||!d.date||!awDateAllowed(d.date))return;cheques.push({id:uid('CHQ'),number:d.number,party:d.party,kind:d.kind,date:d.date,amount:Number(d.amount),bank:d.bank,reference:d.reference,status:d.date>today()?'Post-dated':'Issued',history:[{status:d.date>today()?'Post-dated':'Issued',at:new Date().toISOString()}]});persist();render();};
 document.querySelectorAll('[data-aw-cheque]').forEach(b=>b.onclick=()=>{const x=cheques.find(v=>v.id===b.dataset.awCheque);if(!x)return;const status=prompt('New status: Post-dated, Issued, Deposited, Cleared, Bounced, Cancelled',x.status);if(!status)return;const allowed=['Post-dated','Issued','Deposited','Cleared','Bounced','Cancelled'];if(!allowed.includes(status)){alert('Choose a listed cheque status.');return;}x.status=status;x.history.push({status,at:new Date().toISOString()});persist();render();});
}
function capitalPage(){
 const rows=capitalRows.slice().reverse().map(x=>'<div class="line"><div><b>'+esc(x.number)+' · '+esc(x.kind)+' · '+money(x.amount)+'</b><small>'+esc(x.date)+' · '+esc(x.account||'')+' · '+esc(x.notes||'')+'</small></div></div>').join('');
 return card('Loans, capital and owner drawings','Record owner capital introduced, drawings, loan received and loan repayments. These entries are not yet automatically posted to the double-entry ledger.','<form id="aw-capital"><div class="two"><label>Entry type<select name="kind"><option>Capital introduced</option><option>Owner drawings</option><option>Loan received</option><option>Loan repayment</option></select></label>'+input('date','Date','date','required')+'</div><div class="two">'+input('amount','Amount ₹','number','min=".01" step=".01" required')+input('account','Bank / loan account reference')+'</div>'+text('notes','Notes','rows="2"')+'<button class="primary">Save financial entry</button></form>')+card('Capital and loan register','Manual records; no bank matching or automatic journal posting.',rows||'<div class="empty">No capital or loan entries.</div>');
}
function bindCapital(){const f=document.getElementById('aw-capital');if(!f)return;f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(!d.date||!awDateAllowed(d.date)||!Number.isFinite(Number(d.amount))||Number(d.amount)<=0)return;capitalRows.push({id:uid('CAP'),number:awNextNo('CAP',d.date),...d,amount:Number(d.amount),createdAt:new Date().toISOString()});persist();render();};}
function reportsPage(){
 const stock=read('pa_garment_stock_ledger_v1'),byStyle=new Map();stock.forEach(m=>{const x=byStyle.get(m.style)||{style:m.style,available:0,lastDispatch:''};if(m.type==='Dispatch / sale issue'){x.available-=Number(m.qty||0);if(m.date>x.lastDispatch)x.lastDispatch=m.date}else if(m.type==='Customer return'&&m.status!=='released'){}else if(m.type==='Stock adjustment out')x.available-=Number(m.qty||0);else x.available+=Number(m.qty||0);byStyle.set(m.style,x)});
 const slow=[...byStyle.values()].filter(x=>x.available>0).sort((a,b)=>a.lastDispatch.localeCompare(b.lastDispatch)).slice(0,15);
 const contractorRows=jobs.map(x=>'<div class="line"><div><b>'+esc(x.contractor)+'</b><small>Accepted '+Number(x.accepted||0)+'/'+Number(x.sent||0)+' · Rejected '+Number(x.rejected||0)+' · Rework '+Number(x.rework||0)+'</small></div><strong>'+money(Math.max(0,jobPayable(x)-Number(x.paid||0)))+' due</strong></div>').join('');
 const ar=typeof arOpen==='function'?arOpen():[],receivable=ar.reduce((n,v)=>n+arBal(v),0),dueSoon=ar.filter(v=>arDue(v)>=today()&&arDue(v)<=new Date(Date.now()+30*86400000).toISOString().slice(0,10)).reduce((n,v)=>n+arBal(v),0);
 return card('Slow-moving finished styles','Styles with positive saleable balance and their last recorded dispatch date.',slow.map(x=>'<div class="line"><div><b>'+esc(x.style)+'</b><small>'+x.available+' saleable pcs · Last dispatch '+(x.lastDispatch||'No dispatch recorded')+'</small></div></div>').join('')||'<div class="empty">No saleable stock records.</div>')+card('Contractor efficiency','Local challan data; accepted percentage is shown against pieces sent.',contractorRows||'<div class="empty">No contractor challans.</div>')+card('Receivables forecast','Outstanding invoices due within 30 days. This is not a full cash-flow forecast because bank balances and supplier payables are not included.','<div class="line"><b>Total open receivables</b><strong>'+money(receivable)+'</strong></div><div class="line"><b>Due in next 30 days</b><strong>'+money(dueSoon)+'</strong></div>');
}


let pendingImport=null;
function parseCSV(textValue){
 const s=String(textValue||'').replace(/^\uFEFF/,''),rows=[];let row=[],cell='',quoted=false;
 for(let i=0;i<s.length;i++){const ch=s[i];if(quoted){if(ch==='"'&&s[i+1]==='"'){cell+='"';i++;}else if(ch==='"')quoted=false;else cell+=ch;}else if(ch==='"')quoted=true;else if(ch===','){row.push(cell);cell='';}else if(ch==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=ch;}
 if(cell.length||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}return rows.filter(r=>r.some(x=>String(x).trim()));
}
function importPage(){return card('CSV master and opening-stock import','Choose a CSV template, upload your file, review all rows and errors, then explicitly confirm. Excel/XLSX and PDF import are not enabled in this local phase.','<div class="invoice-actions"><button type="button" class="secondary" data-aw-template="customers">Download customer CSV template</button><button type="button" class="secondary" data-aw-template="stock">Download opening-stock CSV template</button></div><form id="aw-import"><label>Import type<select name="kind"><option value="customers">Customer master</option><option value="stock">Opening garment stock</option></select></label><label>Select CSV file<input id="aw-import-file" type="file" accept=".csv,text/csv" required></label><p class="hint">Nothing is saved until you review the preview and press Confirm Import.</p></form><div id="aw-import-preview"><p class="hint">No file selected.</p></div>')}
function bindImport(){
 const f=document.getElementById('aw-import'),file=document.getElementById('aw-import-file');if(!f||!file)return;
 document.querySelectorAll('[data-aw-template]').forEach(b=>b.onclick=()=>{if(b.dataset.awTemplate==='customers')downloadCSV('Prasad-Customer-Import-Template',[['name','mobile','gstin','city','state','pincode','creditDays','creditLimit','address'],['Example Buyer','9876543210','','Mumbai','Maharashtra','400001','30','0','Full billing address']]);else downloadCSV('Prasad-Opening-Stock-Template',[['date','style','description','colour','size','qty','reason'],[today(),'PA-101','Boys kurta set','Peach','24','10','Verified physical opening count']]);});
 file.onchange=()=>{pendingImport=null;const selected=file.files&&file.files[0];if(!selected)return;if(selected.size>2*1024*1024){alert('CSV file must be 2 MB or smaller.');file.value='';return;}const reader=new FileReader();reader.onload=()=>{try{const rows=parseCSV(reader.result),headers=(rows.shift()||[]).map(x=>String(x).trim().toLowerCase().replace(/[^a-z0-9]/g,'')),kind=f.elements.kind.value,errors=[],records=[];if(!headers.length)throw Error('CSV header row is missing.');const get=(r,k)=>{const i=headers.indexOf(k);return i<0?'':String(r[i]||'').trim();};rows.forEach((r,i)=>{if(r.length!==headers.length){errors.push('Row '+(i+2)+': column count does not match header.');return;}if(kind==='customers'){const x={name:get(r,'name'),mobile:get(r,'mobile').replace(/[\s()+-]/g,''),gstin:get(r,'gstin').toUpperCase(),city:get(r,'city'),state:get(r,'state'),pincode:get(r,'pincode'),creditDays:Number(get(r,'creditdays')||0),creditLimit:Number(get(r,'creditlimit')||0),address:get(r,'address')};if(!x.name||!Number.isFinite(x.creditDays)||x.creditDays<0||!Number.isFinite(x.creditLimit)||x.creditLimit<0||(x.mobile&&!/^\d{10,15}$/.test(x.mobile))||(x.gstin&&!/^\d{2}[0-9A-Z]{13}$/.test(x.gstin))||(x.pincode&&!/^\d{6}$/.test(x.pincode))){errors.push('Row '+(i+2)+': invalid customer name, mobile, GSTIN, PIN or credit values.');return;}const exists=(customerMaster||[]).some(y=>String(y.name||'').toLowerCase()===x.name.toLowerCase()||(x.mobile&&y.mobile===x.mobile)||(x.gstin&&String(y.gstin||'').toUpperCase()===x.gstin));if(exists||records.some(y=>y.name.toLowerCase()===x.name.toLowerCase()||(x.mobile&&y.mobile===x.mobile)||(x.gstin&&y.gstin===x.gstin))){errors.push('Row '+(i+2)+': duplicate customer name, mobile or GSTIN.');return;}records.push(x);}else{const x={date:get(r,'date')||today(),style:get(r,'style'),description:get(r,'description'),colour:get(r,'colour'),size:get(r,'size'),qty:Number(get(r,'qty')),reason:get(r,'reason')};if(!x.style||!x.colour||!x.size||!Number.isInteger(x.qty)||x.qty<1||!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>today()||!x.reason||!awDateAllowed(x.date)){errors.push('Row '+(i+2)+': style, colour, size, whole positive quantity, valid date and reason are required.');return;}const k=[x.style,x.colour,x.size].join('|').toLowerCase();if(records.some(y=>[y.style,y.colour,y.size].join('|').toLowerCase()===k)){errors.push('Row '+(i+2)+': duplicate style/colour/size row in this file. Combine quantities into one row.');return;}records.push(x);}});pendingImport={kind,records,errors,createdAt:new Date().toISOString()};const el=document.getElementById('aw-import-preview');el.innerHTML='<div class="featurelist"><div><b>'+records.length+' valid rows</b><small>'+errors.length+' errors · No records saved yet</small></div>'+(errors.length?errors.map(x=>'<div><b>Needs correction</b><small>'+esc(x)+'</small></div>').join(''):'')+records.slice(0,8).map(x=>'<div><b>'+esc(x.name||x.style)+'</b><small>'+esc(JSON.stringify(x))+'</small></div>').join('')+'</div>'+(records.length&&!errors.length?'<button type="button" class="primary" id="aw-import-confirm">Confirm Import '+records.length+' rows</button>':'<p class="hint">Correct the CSV errors and upload again. Import is blocked while any row has an error.</p>');const confirmBtn=document.getElementById('aw-import-confirm');if(confirmBtn)confirmBtn.onclick=()=>{if(!pendingImport||pendingImport.errors.length||!confirm('Import '+pendingImport.records.length+' '+pendingImport.kind+' rows into this device?'))return;if(pendingImport.kind==='customers'){pendingImport.records.forEach(x=>customerMaster.push({...x,id:uid('CUS'),createdAt:new Date().toISOString()}));localStorage.setItem('pa_customer_master_v1',JSON.stringify(customerMaster));}else{const rows=stockMoves();pendingImport.records.forEach((x,i)=>rows.push({id:uid('GSM'),type:'Opening balance',date:x.date,style:x.style,description:x.description,colour:x.colour,size:x.size,qty:x.qty,reference:'CSV-OPEN-'+pendingImport.createdAt+'-'+i,reason:x.reason,status:'posted',createdAt:new Date().toISOString()}));syncGarmentStock(rows);}const n=pendingImport.records.length;pendingImport=null;persist();render();alert('Imported '+n+' rows. Verify the customer directory or stock ledger.');};}catch(err){alert('Could not read this CSV: '+err.message);}};reader.onerror=()=>alert('Could not read the selected CSV file.');reader.readAsText(selected);};
}

function advancedPage(){
 const tabs=[['returns','Returns & credit notes'],['jobwork','Contractor job work'],['ledger','Accounts ledger'],['sizes','Size sets'],['counts','Stock counts'],['purchaseReturns','Purchase returns'],['prices','Customer prices'],['promises','Collection promises'],['qc','Production QC'],['cutting','Cutting & wastage'],['search','Search & exports'],['financial','Financial year'],['cheques','Cheque register'],['capital','Loans & capital'],['reports','Business reports'],['import','Import masters']];
 let body=awTab==='returns'?returnPage():awTab==='jobwork'?jobPage():awTab==='ledger'?ledgerPage():awTab==='sizes'?sizePage():awTab==='counts'?countPage():awTab==='purchaseReturns'?purchaseReturnPage():awTab==='prices'?pricesPage():awTab==='promises'?promisesPage():awTab==='qc'?qcPage():awTab==='cutting'?cuttingPage():awTab==='search'?searchPage():awTab==='financial'?financialPage():awTab==='cheques'?chequePage():awTab==='capital'?capitalPage():awTab==='reports'?reportsPage():awTab==='import'?importPage():promisesPage();
 return '<div class="heading"><div><small>ADDITIONAL BUSINESS WORKFLOWS</small><h2>Business Control Centre</h2></div><span class="tag">LOCAL</span></div><div class="card"><div class="invoice-actions">'+tabs.map(([k,n])=>'<button type="button" class="secondary" data-aw-tab="'+k+'">'+n+'</button>').join('')+'</div></div>'+body+'<p class="hint" style="margin:15px">These are local workflow additions. Secure shared data, identity-based approvals, audit enforcement, complete automatic accounting postings and full CA validation remain pending. Do not use this prototype as the sole statutory book of accounts.</p>';
}
